let input = $('Webhook').first().json.body.instructions.location || $input.first().json.position;
let location = input;
// If location is "unspecified", use botStatus position instead
if (!input || typeof input !== 'object' || !input.x || !input.y || !input.z) {
  location = $input.first().json.position;
}

let coordinates;

if (typeof location === 'string') {
  const match = location.match(/x:\s*(-?\d+\.?\d*),\s*y:\s*(-?\d+\.?\d*),\s*z:\s*(-?\d+\.?\d*)/);
  if (match) {
    coordinates = {
      x: Math.floor(parseFloat(match[1])),
      y: Math.floor(parseFloat(match[2])),
      z: Math.floor(parseFloat(match[3]))
    };
  }
} else if (typeof location === 'object' && location !== null) {
  coordinates = {
    x: Math.floor(location.x),
    y: Math.floor(location.y),
    z: Math.floor(location.z)
  };
}

return {
  coordinates: coordinates || {},
}

