// n8n execution

function sortBlocksBySequentialPerimeter(blocks) {
    if (!blocks.length) return blocks;

    // Sort by Z first (depth), then X (width) - creates a snake pattern
    return blocks.sort((a, b) => {
        // Primary: sort by Z
        if (a.z !== b.z) return a.z - b.z;

        // Secondary: alternate X direction per row (snake pattern)
        const rowIsEven = (Math.floor(a.z) % 2 === 0);
        return rowIsEven ? a.x - b.x : b.x - a.x;
    });
}

function sortBlocksByPerimeter(blocks) {
    let minX = Infinity, maxX = -Infinity;
    let minZ = Infinity, maxZ = -Infinity;

    for (const b of blocks) {
        minX = Math.min(minX, b.x);
        maxX = Math.max(maxX, b.x);
        minZ = Math.min(minZ, b.z);
        maxZ = Math.max(maxZ, b.z);
    }

    const centerX = (minX + maxX) / 2;
    const centerZ = (minZ + maxZ) / 2;

    return blocks.sort((a, b) => {
        const distA = Math.sqrt((a.x - centerX) ** 2 + (a.z - centerZ) ** 2);
        const distB = Math.sqrt((b.x - centerX) ** 2 + (b.z - centerZ) ** 2);
        return distB - distA;
    });
}

function splitBlueprintByZ(blueprintWrapper, numAgents) {
    const blueprintName = blueprintWrapper.name;
    const blueprint = blueprintWrapper.blueprint;

    console.log(`Blueprint name: ${blueprintName}`);
    console.log(`Levels: ${blueprint.levels.length}`);
    console.log(`Splitting into ${numAgents} agents`);

    // Find Z range across all blocks
    let minZ = Infinity;
    let maxZ = -Infinity;

    for (const level of blueprint.levels) {
        for (const block of level.blocks) {
            const blockZ = block.z;
            minZ = Math.min(minZ, blockZ);
            maxZ = Math.max(maxZ, blockZ);
        }
    }

    const zRange = maxZ - minZ + 1;
    const zPerAgent = zRange / numAgents;

    console.log(`Z range: ${minZ} to ${maxZ} (total: ${zRange})`);
    console.log(`Z per agent: ${zPerAgent.toFixed(2)}`);

    // Create divisions for each agent
    const divisions = [];
    for (let i = 0; i < numAgents; i++) {
        const divMinZ = minZ + (i * zPerAgent);
        const divMaxZ = minZ + ((i + 1) * zPerAgent);
        divisions.push({
            index: i + 1,
            minZ: divMinZ,
            maxZ: divMaxZ,
            blocksByLevel: {}
        });
        console.log(`Division ${i + 1}: Z ${divMinZ.toFixed(2)} to ${divMaxZ.toFixed(2)}`);
    }

    // Assign blocks to divisions
    for (const level of blueprint.levels) {
        const levelId = level.level;

        for (const division of divisions) {
            division.blocksByLevel[levelId] = [];
        }

        for (const block of level.blocks) {
            const blockZ = block.z;

            // Find which division this block belongs to
            let assigned = false;
            for (const div of divisions) {
                if (div.minZ <= blockZ && blockZ < div.maxZ) {
                    div.blocksByLevel[levelId].push(block);
                    assigned = true;
                    break;
                }
            }

            // If not assigned and it's the last division, assign to last division
            if (!assigned && blockZ === maxZ) {
                divisions[divisions.length - 1].blocksByLevel[levelId].push(block);
            }
        }
    }

    // Create output blueprints
    const splitBlueprints = [];

    for (const div of divisions) {
        const bpKey = `${blueprintName}_part${div.index}`;

        const newBlueprintWrapper = {
            _id: blueprintWrapper._id,
            name: bpKey,
           type: blueprintWrapper.type || "construction",
            agent_count: 1,
            blueprint: {
              materials: {},
              levels: []
            },
            initial_inventory: { "0": {} }
        };

        // Build levels with only blocks from this division
        for (const level of blueprint.levels) {
            const levelId = level.level;
            const divisionBlocks = div.blocksByLevel[levelId] || [];

            if (divisionBlocks.length > 0) {
                // Count materials
                for (const block of divisionBlocks) {
                    const material = block.material;
                    newBlueprintWrapper.blueprint.materials[material] = 
                        (newBlueprintWrapper.blueprint.materials[material] || 0) + 1;
                }

                // Create level with blocks from this division
                const sortedBlocks = sortBlocksBySequentialPerimeter(divisionBlocks);
                const newLevel = {
                    level: levelId,
                    coordinates: [...level.coordinates],
                    blocks: sortedBlocks
                };
                newBlueprintWrapper.blueprint.levels.push(newLevel);
            }
        }

        // Populate initial_inventory
        newBlueprintWrapper.initial_inventory["0"] = 
            Object.assign({}, newBlueprintWrapper.materials);

        // Calculate block count
        const totalBlocks = Object.values(newBlueprintWrapper.blueprint.materials)
            .reduce((sum, count) => sum + count, 0);

        console.log(`Agent ${div.index}: Z ${div.minZ.toFixed(1)}-${div.maxZ.toFixed(1)}, ${totalBlocks} total blocks`);

        // Push the blueprint object directly (no wrapper key)
        splitBlueprints.push(newBlueprintWrapper);
    }

    return splitBlueprints;
}


const blueprintWrapper = $('Get Blueprint').first().json;
const numWorkers = $('Webhook').first().json.body.instructions.numWorkers;
const spawnedWorkers = $('SpawnWorkers').first().json.spawnedWorkers;

if (!blueprintWrapper || !numWorkers || !spawnedWorkers) {
    throw new Error('Missing blueprint, numWorkers, or spawnedWorkers');
}

console.log(`Input blueprint name: ${blueprintWrapper.name}`);

// Count original blocks
const originalBlockCount = blueprintWrapper.blueprint.levels.reduce((sum, level) => {
    return sum + (level.blocks ? level.blocks.length : 0);
}, 0);
console.log(`Original blueprint: ${originalBlockCount} blocks`);



// Split the blueprint
const splitBlueprints = splitBlueprintByZ(blueprintWrapper, numWorkers);

// Assign worker names to each split
let totalSplitBlocks = 0;
for (let i = 0; i < splitBlueprints.length; i++) {
    if (spawnedWorkers[i]) {
        splitBlueprints[i].assignedWorker = spawnedWorkers[i].workerName;
        splitBlueprints[i].assignedWorkerPort = spawnedWorkers[i].port;
    }
    // Count blocks in this split
    const splitBlockCount = splitBlueprints[i].blueprint.levels.reduce((sum, level) => {
        return sum + (level.blocks ? level.blocks.length : 0);
    }, 0);

    splitBlueprints[i].blockCount = splitBlockCount;
    totalSplitBlocks += splitBlockCount;

    console.log(`Split ${i + 1}: ${splitBlockCount} blocks (Worker: ${splitBlueprints[i].assignedWorker})`);
}

console.log(`\n✓ Split complete: ${splitBlueprints.length} blueprints created`);
console.log(`  Original: ${originalBlockCount} blocks`);
console.log(`  Split total: ${totalSplitBlocks} blocks`);
console.log(`  Match: ${originalBlockCount === totalSplitBlocks ? '✓ YES' : '✗ NO - blocks lost!'}`);

// Return results
return [
    {
        json: {
            original_blocks: originalBlockCount,
            split_blocks: totalSplitBlocks,
            split_blueprints: splitBlueprints

        }
    }
];

