function sortByPerimeter(blocks) {
    if (!blocks.length) return blocks;

    let minX = Infinity, maxX = -Infinity;
    let minZ = Infinity, maxZ = -Infinity;

    for (const b of blocks) {
        minX = Math.min(minX, b.x);
        maxX = Math.max(maxX, b.x);
        minZ = Math.min(minZ, b.z);
        maxZ = Math.max(maxZ, b.z);
    }

    const centerX = (minX + maxX) / 2;
    const centerZ = (minZ + maxZ) / 2;

    return blocks.sort((a, b) => {
        const distA = Math.sqrt((a.x - centerX) ** 2 + (a.z - centerZ) ** 2);
        const distB = Math.sqrt((b.x - centerX) ** 2 + (b.z - centerZ) ** 2);  // Fixed: centerZ instead of centerB
        return distB - distA;
    });
}

function sortByNearest(blocks, startX = 0, startZ = 0) {
    return blocks.sort((a, b) => {
        const distA = (a.x - startX) ** 2 + (a.z - startZ) ** 2;
        const distB = (b.x - startX) ** 2 + (b.z - startZ) ** 2;
        return distA - distB;
    });
}


const blueprint = $('Set Blueprint').first().json.blueprint;
const strategy = $input.first().json.sortStrategy || 'perimeter';

if (strategy === 'perimeter') {
    for (let level of blueprint.blueprint.levels) {
        level.blocks = sortByPerimeter(level.blocks);
    }
} else if (strategy === 'nearest') {
    for (let level of blueprint.blueprint.levels) {
        level.blocks = sortByNearest(level.blocks);
    }
}

return blueprint;
